from collections import Counter,deque
def f(g):
    H,W=len(g),len(g[0])
    base=Counter(x for r in g for x in r).most_common(1)[0][0]
    def seps(n,axis):
        res=[]
        for idx in range(n):
            line=g[idx] if axis=='h' else [g[r][idx] for r in range(H)]
            cc=Counter(line); m,nm=cc.most_common(1)[0]
            if m!=base and nm>=0.6*len(line): res.append(idx)
        return res
    hrs=seps(H,'h'); vcs=seps(W,'v')
    lc_h={i:Counter(g[i]).most_common(1)[0][0] for i in hrs}
    lc_v={j:Counter([g[r][j] for r in range(H)]).most_common(1)[0][0] for j in vcs}
    sep=set(lc_h.values())|set(lc_v.values())
    out=[[base]*(len(vcs)-1) for _ in range(len(hrs)-1)]
    # components at intersections
    for a in range(len(hrs)):
        for b in range(len(vcs)):
            c=g[hrs[a]][vcs[b]]
            if c not in (base,)*1 and c not in sep:
                # BFS
                q=deque([(a,b)]); comp=[(a,b)]
                while q:
                    i,j=q.popleft()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        ni,nj=i+di,j+dj
                        if 0<=ni<len(hrs) and 0<=nj<len(vcs) and g[hrs[ni]][vcs[nj]]==c and (ni,nj) not in set(comp):
                            comp.append((ni,nj)); q.append((ni,nj))
                # map to bands/regions
                brs=set(i for i,_ in comp); bjs=set(j for _,j in comp)
                b0=min(brs); b1=max(brs); j0=min(bjs); j1=max(bjs)
                for bi in range(b0,b1):
                    for bj in range(j0,j1):
                        out[bi][bj]=c
    return out
